INSERT INTO `addons` (`id`, `slug`, `name`, `version`, `is_active`, `manifest`, `installed_at`, `activated_at`, `created_at`, `updated_at`) VALUES (1,'ai-assistant','AI Assistant','1.0.0',1,'{\"name\": \"AI Assistant\", \"slug\": \"ai-assistant\", \"author\": \"MakeAI\", \"version\": \"1.0.0\", \"settings\": [{\"key\": \"enabled\", \"type\": \"boolean\", \"group\": \"general\", \"label\": \"Enable on Frontend\", \"default\": false, \"description\": \"Show the assistant widget to visitors on the public site.\"}, {\"key\": \"admin_enabled\", \"type\": \"boolean\", \"group\": \"general\", \"label\": \"Enable in Admin Panel\", \"default\": true, \"description\": \"Show the assistant to staff inside the admin panel.\"}, {\"key\": \"auto_open\", \"type\": \"boolean\", \"group\": \"general\", \"label\": \"Auto Open on First Visit\", \"default\": false, \"description\": \"Opens the widget by itself once per browser session.\"}, {\"key\": \"greeting_on_first_visit\", \"type\": \"boolean\", \"group\": \"general\", \"label\": \"Show Greeting & Sound on First Visit\", \"default\": false, \"description\": \"Pops a greeting bubble with a notification chime once per browser session, without opening the full widget.\"}, {\"key\": \"position\", \"type\": \"select\", \"group\": \"general\", \"label\": \"Widget Position\", \"default\": \"bottom-right\", \"options\": [\"bottom-right\", \"bottom-left\", \"header-button\"], \"description\": \"\\\"Header button\\\" replaces the floating bubble with a button in the site header. Themes without a header slot fall back to the bubble.\"}, {\"key\": \"accent_color\", \"type\": \"color\", \"group\": \"general\", \"label\": \"Accent Color\", \"default\": \"#1F75FE\", \"description\": \"Used for the chat bubble, buttons and highlights.\"}, {\"key\": \"excluded_pages\", \"type\": \"textarea\", \"group\": \"general\", \"label\": \"Hide on These Pages\", \"default\": null, \"description\": \"Shown on every page by default. Add one path per line to hide it, e.g. /pricing or /blog/* (a trailing * matches everything under that path). Sign-in, registration and password pages are always excluded.\"}, {\"key\": \"enable_home\", \"type\": \"boolean\", \"group\": \"panels\", \"label\": \"Show Home Tab\", \"default\": true, \"description\": \"A launcher with quick actions, recent chats and popular articles.\"}, {\"key\": \"enable_help\", \"type\": \"boolean\", \"group\": \"panels\", \"label\": \"Show Help Tab\", \"default\": true, \"description\": \"In-widget knowledge-base browser. Requires the Knowledge Base addon.\"}, {\"key\": \"enable_message\", \"type\": \"boolean\", \"group\": \"panels\", \"label\": \"Show \\\"Leave a Message\\\"\", \"default\": true, \"description\": \"A contact form whose submissions land in the admin messages inbox.\"}, {\"key\": \"enable_slash_commands\", \"type\": \"boolean\", \"group\": \"panels\", \"label\": \"Enable Slash Commands\", \"default\": true, \"description\": \"Lets users type / for shortcuts like /help, /usage and /docs.\"}, {\"key\": \"enable_knowledge_base\", \"type\": \"boolean\", \"group\": \"panels\", \"label\": \"Answer from Knowledge Base\", \"default\": true, \"description\": \"Grounds answers in your published help articles and cites them.\"}, {\"key\": \"enable_csat\", \"type\": \"boolean\", \"group\": \"panels\", \"label\": \"Ask for Experience Rating\", \"default\": true, \"description\": \"Asks the user to rate a finished conversation, once per chat.\"}, {\"key\": \"enable_emoji\", \"type\": \"boolean\", \"group\": \"panels\", \"label\": \"Show Emoji Picker\", \"default\": true}, {\"key\": \"allow_file_upload\", \"type\": \"boolean\", \"group\": \"uploads\", \"label\": \"Allow File Upload\", \"default\": false, \"description\": \"Let visitors attach a file for the assistant to read. Admins can always attach.\"}, {\"key\": \"allowed_file_types\", \"type\": \"string\", \"group\": \"uploads\", \"label\": \"Allowed File Types\", \"default\": \"pdf,docx,txt,csv,png,jpg\", \"description\": \"Comma-separated extensions, e.g. pdf,docx,txt. Reading text from images needs a vision-capable model.\"}, {\"key\": \"max_upload_size_mb\", \"type\": \"integer\", \"group\": \"uploads\", \"label\": \"Max Upload Size (MB)\", \"default\": 10, \"description\": \"Largest file a user may attach, in megabytes.\"}, {\"key\": \"assistant_name\", \"type\": \"string\", \"group\": \"persona\", \"label\": \"Assistant Name\", \"default\": \"AI Assistant\"}, {\"key\": \"designation\", \"type\": \"string\", \"group\": \"persona\", \"label\": \"Designation\", \"default\": \"Your AI Helper\", \"description\": \"The subtitle under the name in the widget header.\"}, {\"key\": \"avatar_url\", \"type\": \"file\", \"group\": \"persona\", \"label\": \"Assistant Avatar\", \"default\": null, \"description\": \"Shown on the chat bubble, the header, the Home greeting and every reply. Square images work best; falls back to a robot icon.\"}, {\"key\": \"greeting_message\", \"type\": \"string\", \"group\": \"persona\", \"label\": \"Greeting Message\", \"default\": null, \"description\": \"Leave empty to greet signed-in users by first name.\"}, {\"key\": \"social_whatsapp\", \"type\": \"string\", \"group\": \"channels\", \"label\": \"WhatsApp Link\", \"default\": null}, {\"key\": \"social_telegram\", \"type\": \"string\", \"group\": \"channels\", \"label\": \"Telegram Link\", \"default\": null}, {\"key\": \"social_facebook\", \"type\": \"string\", \"group\": \"channels\", \"label\": \"Facebook Link\", \"default\": null}, {\"key\": \"social_instagram\", \"type\": \"string\", \"group\": \"channels\", \"label\": \"Instagram Link\", \"default\": null}, {\"key\": \"social_x\", \"type\": \"string\", \"group\": \"channels\", \"label\": \"X (Twitter) Link\", \"default\": null}, {\"key\": \"social_website\", \"type\": \"string\", \"group\": \"channels\", \"label\": \"Website Link\", \"default\": null}, {\"key\": \"show_legal_note\", \"type\": \"boolean\", \"group\": \"legal\", \"label\": \"Show Privacy/Terms Note\", \"default\": true, \"description\": \"Hidden automatically unless at least one link below is set.\"}, {\"key\": \"privacy_url\", \"type\": \"string\", \"group\": \"legal\", \"label\": \"Privacy Policy Link\", \"default\": null, \"description\": \"Page slug or full URL, e.g. /privacy-policy. Leave empty to hide.\"}, {\"key\": \"terms_url\", \"type\": \"string\", \"group\": \"legal\", \"label\": \"Terms of Use Link\", \"default\": null, \"description\": \"Page slug or full URL, e.g. /terms. Leave empty to hide.\"}, {\"key\": \"provider\", \"type\": \"string\", \"group\": \"ai\", \"label\": \"AI Provider\", \"default\": null}, {\"key\": \"model\", \"type\": \"string\", \"group\": \"ai\", \"label\": \"AI Model\", \"default\": null}, {\"key\": \"max_tokens\", \"type\": \"integer\", \"group\": \"ai\", \"label\": \"Max Tokens per Reply\", \"default\": 1024, \"description\": \"Caps the length of a single answer.\"}, {\"key\": \"temperature\", \"type\": \"string\", \"group\": \"ai\", \"label\": \"Temperature\", \"default\": \"0.7\", \"description\": \"0 is focused and repeatable; 1 is more creative.\"}, {\"key\": \"show_to\", \"type\": \"select\", \"group\": \"access\", \"label\": \"Who Can Use the Assistant\", \"default\": \"all\", \"options\": [\"all\", \"logged_in\", \"pro_only\"]}, {\"key\": \"guest_daily_message_limit\", \"type\": \"integer\", \"group\": \"access\", \"label\": \"Guest Daily Limit\", \"default\": 5}, {\"key\": \"daily_message_limit\", \"type\": \"integer\", \"group\": \"access\", \"label\": \"Member Daily Limit\", \"default\": 20}, {\"key\": \"pro_daily_message_limit\", \"type\": \"integer\", \"group\": \"access\", \"label\": \"Pro Daily Limit\", \"default\": 0}, {\"key\": \"system_prompt_frontend\", \"type\": \"textarea\", \"group\": \"prompts\", \"label\": \"Frontend System Prompt\", \"secret\": true, \"default\": null}, {\"key\": \"system_prompt_admin\", \"type\": \"textarea\", \"group\": \"prompts\", \"label\": \"Admin System Prompt\", \"secret\": true, \"default\": null}], \"admin_menu\": [{\"icon\": \"ti ti-robot\", \"label\": \"Feedback\", \"route\": \"admin.addons.ai-assistant.feedback\", \"permission\": \"settings.manage\", \"route_pattern\": \"admin.addons.ai-assistant.feedback\"}, {\"icon\": \"ti ti-robot\", \"label\": \"Settings\", \"route\": \"admin.addons.settings\", \"permission\": \"settings.manage\", \"route_params\": {\"slug\": \"ai-assistant\"}, \"route_pattern\": \"admin.addons.*\"}], \"description\": \"Floating AI assistant widget for frontend and admin panel with streaming chat, slash commands, knowledge-base grounding, and feedback.\", \"envato_item_id\": 0, \"requires_license\": 1}','2026-08-05 15:00:52','2026-08-05 15:00:52','2026-08-05 15:00:52','2026-08-05 15:14:05'),(2,'ai-chatbot','AI Chatbot','1.0.0',1,'{\"name\": \"AI Chatbot\", \"slug\": \"ai-chatbot\", \"hooks\": [], \"author\": \"MakeAI\", \"version\": \"1.0.0\", \"settings\": [{\"key\": \"enabled\", \"type\": \"boolean\", \"group\": \"general\", \"label\": \"Enable Chatbot\", \"default\": true}, {\"key\": \"allow_model_select\", \"type\": \"boolean\", \"group\": \"ai\", \"label\": \"Allow Users to Select AI Model\", \"default\": true}, {\"key\": \"show_provider_models\", \"type\": \"boolean\", \"group\": \"ai\", \"label\": \"Show Provider Models\", \"default\": true}, {\"key\": \"show_custom_models\", \"type\": \"boolean\", \"group\": \"ai\", \"label\": \"Show Custom Models\", \"default\": false}, {\"key\": \"custom_models\", \"type\": \"json\", \"group\": \"ai\", \"label\": \"Custom Models\", \"default\": []}, {\"key\": \"mode_default_models\", \"type\": \"json\", \"group\": \"ai\", \"label\": \"Mode Specific Models\", \"default\": []}, {\"key\": \"default_chat_model\", \"type\": \"string\", \"group\": \"ai\", \"label\": \"Default AI Model\", \"default\": \"gpt-5.4-mini\"}, {\"key\": \"enable_knowledge_base\", \"type\": \"boolean\", \"group\": \"general\", \"label\": \"Enable Knowledge Base\", \"default\": true}, {\"key\": \"enable_file_upload\", \"type\": \"boolean\", \"group\": \"general\", \"label\": \"Enable File Upload\", \"default\": true}, {\"key\": \"enable_voice\", \"type\": \"boolean\", \"group\": \"general\", \"label\": \"Enable Voice (mic input & read-aloud)\", \"default\": true}, {\"key\": \"chat_logo\", \"type\": \"file\", \"group\": \"general\", \"label\": \"Chat Logo\", \"default\": null}, {\"key\": \"enabled_modes\", \"type\": \"json\", \"group\": \"ai\", \"label\": \"Available Modes\", \"default\": []}, {\"key\": \"allow_guest_messages\", \"type\": \"boolean\", \"group\": \"guests\", \"label\": \"Allow Guests to Chat\", \"default\": false}, {\"key\": \"guest_max_messages\", \"type\": \"integer\", \"group\": \"guests\", \"label\": \"Max Guest Messages\", \"default\": 10}, {\"key\": \"guest_max_tokens\", \"type\": \"integer\", \"group\": \"guests\", \"label\": \"Max Guest Tokens per Request\", \"default\": 1000}, {\"key\": \"guest_max_chat_history\", \"type\": \"integer\", \"group\": \"guests\", \"label\": \"Max Guest Chat History Messages\", \"default\": 10}, {\"key\": \"guest_max_file_size_mb\", \"type\": \"integer\", \"group\": \"guests\", \"label\": \"Max Guest File Upload Size (MB)\", \"default\": 10}, {\"key\": \"guest_max_messages_5h\", \"type\": \"integer\", \"group\": \"guests\", \"label\": \"Max Guest Messages per 5 Hours\", \"default\": 0}, {\"key\": \"guest_max_messages_weekly\", \"type\": \"integer\", \"group\": \"guests\", \"label\": \"Max Guest Messages per Week\", \"default\": 0}, {\"key\": \"guest_max_messages_monthly\", \"type\": \"integer\", \"group\": \"guests\", \"label\": \"Max Guest Messages per Month\", \"default\": 0}, {\"key\": \"free_credits_per_message\", \"type\": \"integer\", \"group\": \"free_tier\", \"label\": \"Credits per Message\", \"default\": 1}, {\"key\": \"free_max_tokens\", \"type\": \"integer\", \"group\": \"free_tier\", \"label\": \"Max Tokens per Request\", \"default\": 2048}, {\"key\": \"free_max_c