INSERT INTO `ai_assistant_feedback` (`id`, `message_id`, `user_id`, `session_id`, `context_page`, `message_hash`, `rating`, `comment`, `created_at`, `updated_at`) VALUES (1,2,2,'demo-assistant-credits-0001','/user/dashboard','517948c9e25b4a08aae1554c99638654f48b2a72',1,'Exactly the number I needed, thanks.','2026-08-05 09:02:40','2026-08-05 09:02:40'),(2,4,2,'demo-assistant-credits-0001','/user/dashboard','7f10e508dff6d0ea1d206d3d20649c523843644a',1,NULL,'2026-08-05 09:06:40','2026-08-05 09:06:40'),(3,6,6,'demo-assistant-pricing-0002','/pricing','9ac832bf1415e0391285d34ba7d3e9b0e8d82db1',1,NULL,'2026-08-04 10:09:40','2026-08-04 10:09:40'),(4,8,6,'demo-assistant-pricing-0002','/pricing','3c8134b6aaf740f931049cd13ecf9c90f3dc2c61',-1,'Dodged the question — I wanted the actual yearly price.','2026-08-04 10:13:40','2026-08-04 10:13:40'),(5,10,NULL,'demo-assistant-guest-0003','/','33d5e0fb04b3e40c954404810835be8f9f85e7f9',1,NULL,'2026-08-03 11:16:40','2026-08-03 11:16:40'),(6,12,10,'demo-assistant-tools-0004','/ai-tools','d2c8ce229660f7a09cef757b3ebfcb18397d8728',1,NULL,'2026-08-02 12:23:40','2026-08-02 12:23:40'),(7,14,10,'demo-assistant-tools-0004','/ai-tools','1aae1fad239b87facbf6879bf5fa134710b95891',-1,'I need a proper CSV import. This did not solve my problem.','2026-08-02 12:27:40','2026-08-02 12:27:40'),(8,16,15,'demo-assistant-billing-0005','/user/dashboard/billing','c770b1008b09d9a1335819680bf31f6408be08fc',1,'Clear and it worked first time.','2026-08-01 13:30:40','2026-08-01 13:30:40'),(9,18,1,'demo-assistant-admin-0006','/admin/dashboard','f65d199d48996acd64eb4abeef46dbc70e1cb07d',1,NULL,'2026-08-04 14:37:40','2026-08-04 14:37:40'),(10,20,1,'demo-assistant-admin-0006','/admin/dashboard','4e3b68af40f84d550102687da33dacd8a5401750',1,'Did not know about the fallback behaviour.','2026-08-04 14:41:40','2026-08-04 14:41:40'),(11,22,23,'demo-assistant-docs-0007','/blog','491700fbfad46cbc7bb0b26abf07d8fb13d0298c',-1,'The article it linked is out of date, endpoints have moved.','2026-07-31 15:44:40','2026-07-31 15:44:40'),(12,24,NULL,'demo-assistant-refund-0008','/pricing','88acb1dd972c7d97290ed6d16936bb2cc52d803f',1,NULL,'2026-07-30 16:51:40','2026-07-30 16:51:40'),(13,26,NULL,'demo-assistant-refund-0008','/pricing','e5befe5d306b6ddf698ad2ad5612dc5aeb2d292a',1,NULL,'2026-07-30 16:55:40','2026-07-30 16:55:40'),(14,28,34,'demo-assistant-failure-0009','/user/dashboard/documents','79fdcd9c9cf5938eb9943bbf47c46a1932de44c5',1,'Was out of credits. Would not have found that on my own.','2026-07-28 17:58:40','2026-07-28 17:58:40'),(15,30,47,'demo-assistant-affiliate-0010','/user/dashboard/affiliate','11f80d68b6711b483682892c8fa74485e00643a1',1,NULL,'2026-07-25 09:05:40','2026-07-25 09:05:40');
