INSERT INTO `ai_tools` (`id`, `ulid`, `name`, `slug`, `type`, `description`, `prompt_system`, `prompt_user`, `category_id`, `icon`, `color`, `fields`, `tags`, `output_type`, `model_override`, `generation_mode`, `integration_slug`, `max_tokens_override`, `temperature`, `max_variants`, `show_improve`, `access_level`, `is_active`, `show_header`, `show_footer`, `is_embeddable`, `is_featured`, `is_system`, `supports_brand_voice`, `sort_order`, `usage_count`, `views_count`, `avg_output_tokens`, `avg_rating`, `review_count`, `meta_title`, `meta_description`, `og_image`, `about_content`, `how_it_works`, `usage_examples`, `faq_items`, `show_about`, `show_how_it_works`, `show_usage_examples`, `show_faqs`, `show_reviews`, `show_related_tools`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,NULL,'Blog Article','blog-article','text','Use Blog Article to create engaging, SEO-ready blog content in seconds. Guided inputs, editable output, ready to use.','You are a senior content writer and SEO strategist producing a complete, publish-ready long-form article.\n\n- Open with a hook that names the reader\'s problem and the payoff of reading on — no \"In today\'s world\" throat-clearing.\n- Structure the piece with logical, descriptive, search-friendly H2/H3 headings.\n- Develop each section with specific detail, examples, and concrete takeaways; never filler or repetition.\n- Weave the target keywords in naturally — never keyword-stuff.\n- Close with a tight conclusion and, where it fits, a clear call to action.\n- Be accurate: no invented statistics, studies, or quotes; mark any needed citation as a [placeholder].\n\nReturn clean Markdown. Always respond in {language}.','Topic or task: {topic}\nContext: {description}\nTarget audience: {audience}\nTone: {tone}\nFormat: {format}\nKey points: {keywords}\nAdditional instructions: {additional}',1,'ti ti-file-text','#10b981','[{\"key\": \"topic\", \"name\": \"topic\", \"type\": \"text\", \"label\": \"Topic or Task\", \"required\": true, \"max_length\": 200}, {\"key\": \"description\", \"name\": \"description\", \"rows\": 4, \"type\": \"textarea\", \"label\": \"Context\", \"required\": false}, {\"key\": \"audience\", \"name\": \"audience\", \"type\": \"text\", \"label\": \"Target Audience\", \"required\": false}, {\"key\": \"tone\", \"name\": \"tone\", \"type\": \"tone_select\", \"label\": \"Tone of Voice\", \"default\": \"Professional\"}, {\"key\": \"language\", \"name\": \"language\", \"type\": \"language_select\", \"label\": \"Output Language\", \"default\": \"English\"}, {\"key\": \"length\", \"name\": \"length\", \"type\": \"length_select\", \"label\": \"Output Length\", \"default\": \"medium\"}, {\"key\": \"format\", \"name\": \"format\", \"type\": \"select\", \"label\": \"Format\", \"default\": \"Markdown\", \"options\": [\"Paragraph\", \"Bullet Points\", \"Numbered List\", \"Table\", \"Markdown\"]}, {\"key\": \"keywords\", \"name\": \"keywords\", \"type\": \"tags_input\", \"label\": \"Keywords or Key Points\", \"required\": false}, {\"key\": \"additional\", \"name\": \"additional\", \"rows\": 3, \"type\": \"textarea\", \"label\": \"Additional Instructions\", \"required\": false}]','{\"content_type\": \"articles\"}','markdown',NULL,'llm',NULL,300,0.70,3,1,'inherit',1,1,1,1,1,1,1,1,17478,40046,300,3.67,6,'Blog Article - Free AI Tool','Use Blog Article to create engaging, SEO-ready blog content in seconds. Guided inputs, editable output, ready to use.',NULL,'Blog Article is an AI-powered Blog & Content tool that turns a few guided inputs into engaging, SEO-ready blog content. Set the tone, format, and language to fit your needs, then copy, export, or refine the result — no writing or design skills required.','[{\"step\": 1, \"title\": \"Add details\", \"description\": \"Fill in the main topic, audience, and any required context.\"}, {\"step\": 2, \"title\": \"Choose style\", \"description\": \"Select tone, language, format, and output length where needed.\"}, {\"step\": 3, \"title\": \"Generate\", \"description\": \"Review the AI output, then copy, export, save, or regenerate it.\"}]','[{\"input\": {\"topic\": \"10 ways to improve remote team productivity\"}, \"title\": \"Example\", \"output\": \"A publish-ready article with headings and a conclusion.\"}]','[{\"answer\": \"It runs on your account plan. Generate as many results as your plan allows.\", \"question\": \"Is Blog Article free to use?\"}, {\"answer\": \"Yes. Every result is an editable draft — copy it, save it, export it, or regenerate for a fresh take.\", \"question\": \"Can I edit the Blog Article output?\"}, {\"answer\": \"Choose your output language in the form and the result is written in that language.\", \"question\": \"What languages are supported?\"}]',1,1,1,1,1,1,'2026-08-05 15:00:50','2026-08-05 15:01:25',NULL),(2,NULL,'Blog Intro','blog-intro','text','Use Blog Intro to create engaging, SEO-ready blog content in seconds. Guided inputs, editable output, ready to use.','You are an expert Blog & Content specialist operating the \"Blog Intro\" tool.\n\nCore rules:\n- Produce practical, specific, ready-to-use output that directly serves the request.\n- Honor the requested tone, audience, language, length, and format exactly.\n- Be accurate. Never invent facts, statistics, names, quotes, or sources; if something is unknown, say so or leave a clearly marked placeholder.\n- Make reasonable assumptions when the input is thin, and keep the result easy to edit.\n- Return only the requested content — no preamble, apologies, or meta-commentary.\n\nArticle rules:\n- Write a strong intro, scannable headings, and a natural conclusion.\n- Be accurate and readable; never keyword-stuff.\n\nFormat: return clean, well-structured Markdown — headings, short paragraphs, bold for emphasis, and lists or tables where they aid clarity.\n\nAlways respond in {language}.','Topic or task: {topic}\nContext: {description}\nTarget audience: {audience}\nTone: {tone}\nFormat: {format}\nKey points: {keywords}\nAddition