INSERT INTO `aip_presets` (`id`, `name`, `slug`, `prompt_suffix`, `negative_prompt`, `thumb_path`, `sort`, `is_active`, `created_at`, `updated_at`) VALUES (1,'Photorealistic','photorealistic',', photorealistic, ultra realistic, sharp focus, natural lighting, high detail, 8k, shot on DSLR','illustration, cartoon, painting, drawing, anime, low quality, blurry, deformed','ai-image-pro/demo/aurora-portrait.svg',1,1,'2026-08-05 15:00:53','2026-08-05 15:01:43'),(2,'Cinematic','cinematic',', cinematic still, anamorphic lens, dramatic key light, film grain, muted teal and amber grade','flat lighting, snapshot, low contrast','ai-image-pro/demo/neon-alley.svg',20,1,'2026-06-26 15:01:43','2026-06-26 15:01:43'),(3,'Anime','anime',', anime style, cel shading, vibrant colors, clean line art, detailed anime illustration, studio quality','photorealistic, 3d render, realistic, blurry, extra limbs, bad anatomy','ai-image-pro/demo/floating-city.svg',3,1,'2026-08-05 15:00:53','2026-08-05 15:01:43'),(4,'3D Render','3d-render',', octane render, soft global illumination, subsurface scattering, physically based materials, 8k','flat 2d, line art, sketch','ai-image-pro/demo/ceramic-hero.svg',22,1,'2026-06-28 15:01:43','2026-06-28 15:01:43'),(5,'Watercolor','watercolor',', watercolor painting, soft color washes, blended pigments, textured paper, delicate brush strokes, artistic','photograph, 3d render, sharp edges, digital, harsh lines','ai-image-pro/demo/paper-texture.svg',5,1,'2026-08-05 15:00:53','2026-08-05 15:01:43'),(6,'Line Art','line-art',', clean vector line art, single weight strokes, generous negative space, monochrome','gradient, photographic texture, noise','ai-image-pro/demo/ink-botanical.svg',23,1,'2026-06-29 15:01:43','2026-06-29 15:01:43'),(7,'Product Shot','product-shot',', professional product photography, studio lighting, seamless white background, soft shadows, high detail, commercial','cluttered background, harsh shadows, low quality, blurry, distracting elements','ai-image-pro/demo/studio-ceramic.svg',7,1,'2026-08-05 15:00:53','2026-08-05 15:01:43'),(8,'Cyberpunk Neon','cyberpunk-neon',', cyberpunk, neon lights, futuristic city, glowing signs, rain-soaked streets, high contrast, vibrant magenta and cyan','daylight, natural, rural, muted colors, vintage, sepia','ai-image-pro/demo/neon-alley.svg',8,1,'2026-08-05 15:00:53','2026-08-05 15:01:43'),(9,'Oil Painting','oil-painting',', oil painting, thick impasto brush strokes, rich textures, classical technique, canvas texture, painterly','photograph, digital art, 3d render, smooth, flat, low detail','ai-image-pro/demo/desert-road.svg',9,1,'2026-08-05 15:00:53','2026-08-05 15:01:43'),(10,'Minimal','minimal',', minimalist, clean composition, generous negative space, simple shapes, muted palette, flat design, elegant','cluttered, busy, ornate, detailed background, noisy, chaotic','ai-image-pro/demo/ink-botanical.svg',10,1,'2026-08-05 15:00:53','2026-08-05 15:01:43'),(11,'Illustration','illustration',', digital illustration, painterly brushwork, rich colour palette, expressive shapes','photograph, realistic skin texture','ai-image-pro/demo/floating-city.svg',21,1,'2026-06-27 15:01:43','2026-06-27 15:01:43');
