INSERT INTO `announcements` (`id`, `type`, `title`, `content`, `bg_color`, `text_color`, `cta_text`, `cta_url`, `image`, `target_audience`, `trigger_type`, `trigger_value`, `show_frequency`, `is_active`, `starts_at`, `ends_at`, `created_by`, `created_at`, `updated_at`) VALUES (1,'topbar','Summer launch: 30% off annual plans','Upgrade before the end of the month and save 30% on any annual subscription.','#1f75fe','#ffffff','View plans','/pricing',NULL,'all',NULL,NULL,'session',1,'2026-07-30 15:01:38','2026-08-29 15:01:38',2,'2026-07-28 11:04:00','2026-07-28 11:04:00'),(2,'popup','Start creating for free','Create an account and get monthly credits to try every AI tool — no card required.','#111827','#ffffff','Create free account','/register',NULL,'guests','delay','8','session',1,'2026-07-16 15:01:38',NULL,2,'2026-07-14 11:26:00','2026-07-14 11:26:00'),(3,'bottom_popup','Running low on credits?','Pro unlocks every model, unlimited chats and priority generation queues.','#8b5cf6','#ffffff','Compare plans','/pricing',NULL,'free','scroll','55','once',1,'2026-07-24 15:01:38',NULL,2,'2026-07-22 12:45:00','2026-07-22 12:45:00'),(4,'notification','New: document collections','Group your saved documents into collections and share them with your team.','#059669','#ffffff','See what is new','/blog',NULL,'auth','immediate',NULL,'once',1,'2026-08-02 15:01:38','2026-08-16 15:01:38',2,'2026-07-31 13:57:00','2026-07-31 13:57:00'),(5,'popup','Switch to annual and save two months','You are on a monthly plan — moving to annual billing works out cheaper from day one.','#0f172a','#ffffff','Switch to annual','/user/dashboard/billing',NULL,'pro','exit',NULL,'once',1,'2026-08-12 15:01:38','2026-09-11 15:01:38',2,'2026-08-10 12:03:00','2026-08-10 12:03:00'),(6,'topbar','Scheduled maintenance completed','Thanks for your patience — the platform is fully operational again.','#f59e0b','#111827',NULL,NULL,NULL,'all',NULL,NULL,'always',0,'2026-06-18 15:01:38','2026-06-21 15:01:38',2,'2026-06-16 17:10:00','2026-06-16 17:10:00');
