INSERT INTO `categories` (`id`, `name`, `slug`, `description`, `icon`, `color`, `type`, `parent_id`, `is_active`, `is_system`, `requires_pro`, `requires_login`, `access_level`, `sort_order`, `tools_count`, `meta_title`, `meta_description`, `created_at`, `updated_at`) VALUES (1,'Blog & Content','blog-content','Blog posts, articles, rewriting, summaries, and editorial content.','ti ti-file-text','#10b981','ai_tool',NULL,1,1,0,0,'inherit',1,23,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:50'),(2,'Social Media','social-media','Posts, captions, hashtags, scripts, bios, and platform-specific content.','ti ti-brand-instagram','#ec4899','ai_tool',NULL,1,1,0,0,'inherit',2,38,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:50'),(3,'Advertising','advertising','Ad headlines, scripts, copywriting formulas, and paid campaign assets.','ti ti-speakerphone','#f59e0b','ai_tool',NULL,1,1,0,0,'inherit',3,18,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:50'),(4,'Email Marketing','email-marketing','Cold emails, newsletters, sequences, sales emails, and lifecycle messaging.','ti ti-mail','#3b82f6','ai_tool',NULL,1,1,0,0,'inherit',4,18,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:50'),(5,'Ecommerce','ecommerce','Product descriptions, listings, reviews, carts, and store copy.','ti ti-shopping-cart','#8b5cf6','ai_tool',NULL,1,1,0,0,'inherit',5,23,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:50'),(6,'Business','business','Plans, strategy, operations, reports, OKRs, and professional workflows.','ti ti-briefcase','#6366f1','ai_tool',NULL,1,1,0,0,'inherit',6,29,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:50'),(7,'Academic','academic','Essays, lessons, quizzes, research help, and educational materials.','ti ti-school','#14b8a6','ai_tool',NULL,1,1,0,0,'inherit',7,21,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:50'),(8,'Development','development','Code generation, debugging, tests, documentation, and developer productivity.','ti ti-code','#f97316','ai_tool',NULL,1,1,0,0,'inherit',8,19,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:50'),(9,'Website & SEO','website-seo','SEO, landing pages, site copy, schema, and legal web pages.','ti ti-world','#06b6d4','ai_tool',NULL,1,1,0,0,'inherit',9,26,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(10,'Creative Writing','creative-writing','Stories, poems, lyrics, scripts, dialogue, and creative ideation.','ti ti-pencil','#a855f7','ai_tool',NULL,1,1,0,0,'inherit',10,14,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(11,'Personal & Career','personal-career','Bios, resumes, letters, career negotiation, and personal branding.','ti ti-user','#64748b','ai_tool',NULL,1,1,0,0,'inherit',11,10,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(12,'Health & Fitness','health-fitness','Fitness plans, meals, recipes, wellness, and habit support.','ti ti-heart','#ef4444','ai_tool',NULL,1,1,0,0,'inherit',12,7,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(13,'Real Estate','real-estate','Listings, guides, market notes, and investment analysis.','ti ti-building','#78716c','ai_tool',NULL,1,1,0,0,'inherit',13,5,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(14,'Entertainment','entertainment','Travel, events, trivia, gifts, games, and leisure ideas.','ti ti-device-gamepad','#84cc16','ai_tool',NULL,1,1,0,0,'inherit',14,8,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(15,'Language','language','Translation, grammar, tone, vocabulary, and language learning.','ti ti-language','#0ea5e9','ai_tool',NULL,1,1,0,0,'inherit',15,7,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(16,'Marketing Strategy','marketing-strategy','Brand voice, audiences, competitors, positioning, and GTM planning.','ti ti-chart-arrows','#d946ef','ai_tool',NULL,1,1,0,0,'inherit',16,20,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(17,'Customer Support','customer-support','Ticket replies, help docs, onboarding, scripts, and support workflows.','ti ti-headset','#22c55e','ai_tool',NULL,1,1,0,0,'inherit',17,8,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(18,'Legal & Finance','legal-finance','Legal summaries, policies, disclaimers, finance, and fundraising copy.','ti ti-scale','#94a3b8','ai_tool',NULL,1,1,0,0,'inherit',18,15,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(19,'Productivity','productivity','Planning, goals, decisions, action plans, guides, and prompts.','ti ti-checklist','#fb923c','ai_tool',NULL,1,1,0,0,'inherit',19,16,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(20,'Sales','sales','Cold outreach, proposals, objection handling, follow-ups, and closing.','ti ti-businessplan','#0d9488','ai_tool',NULL,1,1,0,0,'inherit',20,10,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(21,'HR & Recruiting','hr-recruiting','Job ads, interviews, offers, onboarding, reviews, and people ops.','ti ti-users-group','#7c3aed','ai_tool',NULL,1,1,0,0,'inherit',21,10,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(22,'Podcast & Audio','podcast','Episode outlines, show notes, titles, descriptions, and interview questions.','ti ti-microphone-2','#db2777','ai_tool',NULL,1,1,0,0,'inherit',22,6,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(23,'AI Prompts','ai-prompts','Prompts for image models, ChatGPT, and AI agents.','ti ti-sparkles','#2563eb','ai_tool',NULL,1,1,0,0,'inherit',23,6,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(24,'Video','video','Scripts, storyboards, shot lists, briefs, and video production planning.','ti ti-video','#e11d48','ai_tool',NULL,1,1,0,0,'inherit',24,22,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(25,'Image & Design','image-design','Captions, design briefs, moodboards, palettes, and image metadata.','ti ti-photo','#7c3aed','ai_tool',NULL,1,1,0,0,'inherit',25,23,NULL,NULL,'2026-08-05 15:00:50','2026-08-05 15:00:51'),(26,'📚 Document AI','document-ai','Chat with PDFs, documents, spreadsheets, websites, and YouTube videos. Summarize, compare, and write from your knowledge base.','ti ti-file-search','#0891b2','ai_tool',NULL,1,1,0,0,'inherit',20,8,NULL,NULL,'2026-08-05 15:00:51','2026-08-05 15:00:51');
