INSERT INTO `chat_projects` (`id`, `user_id`, `name`, `description`, `color_hex`, `created_at`, `updated_at`) VALUES (1,2,'Q3 Content Engine','Pillar pages, comparison posts and the monthly newsletter.','#6366F1','2026-07-02 09:15:00','2026-07-02 09:15:00'),(2,2,'Client — Northwind','Onboarding docs, call recaps and their quarterly report.','#0EA5E9','2026-07-14 09:15:00','2026-07-14 09:15:00'),(3,2,'Product Launch','Everything for the March release: emails, social, landing copy.','#F59E0B','2026-07-28 09:15:00','2026-07-28 09:15:00');
