INSERT INTO `documents` (`id`, `user_id`, `title`, `content`, `tool_slug`, `word_count`, `created_at`, `updated_at`) VALUES (1,2,'Q3 AI Launch Campaign','<h1>Q3 AI Launch Campaign</h1><p>Position MakeAI as the fastest way for founders to turn ideas into launch-ready assets.</p><p>Focus on polished outputs, premium visuals, and speed-to-value for buyers.</p>','abandoned-cart-email',28,'2026-08-02 14:20:00','2026-08-02 14:20:00'),(2,2,'Premium Dashboard Value Pitch','<h1>Premium Dashboard Value Pitch</h1><p>Lead with clarity, momentum, and polished analytics.</p><p>Showcase believable activity so buyers can imagine running a real SaaS from day one.</p>','about-us-page',25,'2026-08-03 13:20:00','2026-08-03 13:20:00'),(3,2,'Founder Outreach Sequence','<h1>Founder Outreach Sequence</h1><p>Use outcome-first messaging with short, confident calls to action.</p><p>Keep tone consultative and premium.</p>','abstract-writer',17,'2026-08-04 12:20:00','2026-08-04 12:20:00'),(4,2,'Weekly Content Operations','<h1>Weekly Content Operations</h1><p>Bundle blog, email, and social outputs into one repeatable workflow.</p><p>Measure production speed, approval rate, and content reuse.</p>','academic-cover-letter',21,'2026-08-05 11:20:00','2026-08-05 11:20:00');
