INSERT INTO `mail_templates` (`id`, `slug`, `name`, `subject`, `content`, `is_active`, `is_system`, `requires_pro`, `category`, `last_edited_by`, `created_at`, `updated_at`) VALUES (1,'email_verify_otp','Email Verification OTP','{otp_code} is your verification code','<h1>Verify Your Email</h1><p>Hi {user_name},</p><p>Your verification code is: <strong>{otp_code}</strong></p><p>Thanks, {site_name}</p>',1,1,0,'auth',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(2,'reset_password_otp','Reset Password OTP','{otp_code} is your password reset code','<h1>Reset Your Password</h1><p>Hi {user_name},</p><p>You requested a password reset. Use the code below to continue:</p><h2>{otp_code}</h2><p>This code will expire soon.</p>',1,1,0,'auth',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(3,'login_otp','Login OTP (2FA via email)','{otp_code} is your login code','<h1>Login Verification</h1><p>Hi {user_name},</p><p>Use this code to complete your login:</p><h2>{otp_code}</h2><p>If this was not you, please secure your account.</p>',1,1,0,'auth',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(4,'welcome','Welcome / New Account Created','Welcome to {site_name}!','<h1>Welcome aboard!</h1><p>Hi {user_name},</p><p>We are excited to have you with us. Start creating amazing content today!</p><p><a href=\"{site_url}\">Go to Dashboard</a></p>',1,1,0,'account',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(5,'password_changed','Password Changed Notification','Security Alert: Your password has been changed','<h1>Security Notification</h1><p>Hi {user_name},</p><p>This is a confirmation that your password has been successfully changed. If you did not perform this action, please contact support immediately.</p>',1,1,0,'account',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(6,'email_changed','Email Address Changed','Your email address was changed','<h1>Email Changed</h1><p>Hi {user_name},</p><p>Your account email address was changed to {user_email}.</p><p>If you did not request this change, please contact support.</p>',1,1,0,'account',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(7,'account_suspended','Account Suspended','Your account has been suspended','<h1>Account Suspended</h1><p>Hi {user_name},</p><p>Your account has been suspended. Please contact support if you believe this is a mistake.</p>',1,1,0,'account',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(8,'account_activated','Account Activated','Your account is active again','<h1>Account Activated</h1><p>Hi {user_name},</p><p>Your account has been activated. You can sign in and continue using {site_name}.</p>',1,1,0,'account',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(9,'credits_added','Credits Added to Account','Credits added to your account','<h1>Credits Added</h1><p>Hi {user_name},</p><p>{credits} credits were added to your account.</p>',1,1,0,'account',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(10,'credits_low','Low Credit Balance Warning','Your credit balance is low','<h1>Low Credit Balance</h1><p>Hi {user_name},</p><p>Your current credit balance is {credits}. Add more credits to keep generating without interruption.</p>',1,1,0,'account',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(11,'referral_earned','Referral — Credits Earned','You earned {credits} referral credits','<h1>Referral Credits Earned</h1><p>Hi {user_name},</p><p><strong>{credits}</strong> referral credits have been added to your account because someone you referred signed up.</p><p><a href=\"{site_url}\">View your affiliate dashboard</a></p>',1,1,0,'account',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(12,'admin_announcement','Admin Announcement / Broadcast','Announcement from {site_name}','<h1>Announcement</h1><p>Hi {user_name},</p><p>{message}</p>',1,1,0,'account',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(13,'subscription_started','Subscription Started / Welcome to Plan','Welcome to {plan_name}','<h1>Subscription Started</h1><p>Hi {user_name},</p><p>Your {plan_name} subscription is now active.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(14,'subscription_renewed','Subscription Renewed Successfully','Your subscription was renewed','<h1>Subscription Renewed</h1><p>Hi {user_name},</p><p>Your {plan_name} subscription has been renewed successfully.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(15,'subscription_expiring_soon','Subscription Expiring Soon (3 days)','Your subscription expires soon','<h1>Subscription Expiring Soon</h1><p>Hi {user_name},</p><p>Your {plan_name} subscription expires soon. Renew now to avoid interruption.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(16,'subscription_expired','Subscription Expired','Your subscription has expired','<h1>Subscription Expired</h1><p>Hi {user_name},</p><p>Your {plan_name} subscription has expired. Upgrade to continue using Pro features.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(17,'subscription_canceled','Subscription Canceled','Your subscription was canceled','<h1>Subscription Canceled</h1><p>Hi {user_name},</p><p>Your {plan_name} subscription has been canceled.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(18,'subscription_ended','Subscription Ended by Administrator','Your subscription has been ended','<h1>Subscription Ended</h1><p>Hi {user_name},</p><p>Your {plan_name} subscription was ended by an administrator and your access has been removed. {reason}</p><p>If you have any questions, please contact our support team.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(19,'subscription_upgraded','Plan Upgraded','Your plan was upgraded','<h1>Plan Upgraded</h1><p>Hi {user_name},</p><p>Your subscription has been upgraded to {plan_name}.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(20,'subscription_downgraded','Plan Downgraded','Your plan was downgraded','<h1>Plan Downgraded</h1><p>Hi {user_name},</p><p>Your subscription has been changed to {plan_name}.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(21,'subscription_payment_failed','Payment Failed / Retry Notice','Payment failed for your subscription','<h1>Payment Failed</h1><p>Hi {user_name},</p><p>We could not process your payment for {plan_name}. Please update your billing details.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(22,'subscription_trial_started','Trial Started','Your trial has started','<h1>Trial Started</h1><p>Hi {user_name},</p><p>Your {plan_name} trial has started. Enjoy exploring Pro features.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(23,'subscription_trial_expiring','Trial Expiring Soon (1 day)','Your trial expires soon','<h1>Trial Expiring Soon</h1><p>Hi {user_name},</p><p>Your {plan_name} trial expires soon. Upgrade now to keep access.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(24,'subscription_trial_ended','Trial Ended - Upgrade Now','Your trial has ended','<h1>Trial Ended</h1><p>Hi {user_name},</p><p>Your trial has ended. Upgrade to continue using Pro features.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(25,'invoice_paid','Invoice / Receipt','Receipt for your payment','<h1>Payment Receipt</h1><p>Hi {user_name},</p><p>Thank you for your payment for {plan_name}. Your invoice is now paid.</p>',1,1,1,'subscription',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(26,'newsletter_confirm','Newsletter Subscription Confirmation (double opt-in)','Please confirm your subscription','<h1>Confirm Subscription</h1><p>Click below to join our newsletter and get the latest updates.</p><p><a href=\"{confirm_url}\">Confirm Now</a></p>',1,1,0,'newsletter',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(27,'newsletter_unsubscribed','Unsubscribe Confirmation','You have been unsubscribed','<h1>Unsubscribed</h1><p>You have been removed from the {site_name} newsletter list.</p>',1,1,0,'newsletter',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(28,'newsletter_campaign','Newsletter Campaign (base template)','{campaign_subject}','<h1>{campaign_title}</h1><p>{campaign_content}</p><p><a href=\"{unsubscribe_url}\">Unsubscribe</a></p>',1,1,0,'newsletter',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(29,'affiliate_commission_earned','Affiliate — Commission Earned','You earned a commission of {amount}','<h1>Commission Earned 🎉</h1><p>Hi {user_name},</p><p>Great news — you just earned a commission of <strong>{amount}</strong> on {site_name}.</p><p><a href=\"{site_url}\">View your affiliate dashboard</a></p>',1,1,0,'affiliate',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(30,'affiliate_commission_rejected','Affiliate — Commission Rejected','A commission of {amount} was reversed','<h1>Commission Reversed</h1><p>Hi {user_name},</p><p>A commission of <strong>{amount}</strong> on {site_name} has been reversed (for example, the referred purchase was refunded or did not qualify).</p><p><a href=\"{site_url}\">View your affiliate dashboard</a></p>',1,1,0,'affiliate',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(31,'affiliate_payout_paid','Affiliate — Payout Sent','Your payout of {amount} has been sent','<h1>Payout Sent 💸</h1><p>Hi {user_name},</p><p>Your affiliate payout of <strong>{amount}</strong> has been sent via {method}.</p><p><a href=\"{site_url}\">View your affiliate dashboard</a></p>',1,1,0,'affiliate',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(32,'affiliate_payout_rejected','Affiliate — Payout Rejected','Your payout request of {amount} was declined','<h1>Payout Request Declined</h1><p>Hi {user_name},</p><p>Your affiliate payout request of <strong>{amount}</strong> on {site_name} was declined. Please review your payout details or contact support.</p><p><a href=\"{site_url}\">View your affiliate dashboard</a></p>',1,1,0,'affiliate',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(33,'ticket_created','Support — Ticket Received (to customer)','[{ticket_number}] We received your ticket: {ticket_subject}','<h1>We received your ticket</h1><p>Hi {user_name},</p><p>Thanks for getting in touch. Your ticket <strong>{ticket_number}</strong> — \"{ticket_subject}\" — has been received and our support team will reply as soon as possible.</p><p><a href=\"{ticket_url}\">View your ticket</a></p><p>— The {site_name} support team</p>',1,1,0,'support',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(34,'ticket_created_admin','Support — New Ticket (to support team)','[{ticket_number}] New {ticket_priority} priority ticket: {ticket_subject}','<h1>New support ticket</h1><p>Hi {user_name},</p><p><strong>{customer_name}</strong> opened ticket <strong>{ticket_number}</strong> ({ticket_priority} priority) in {ticket_department}.</p><p><strong>Subject:</strong> {ticket_subject}</p><p><a href=\"{ticket_url}\">Open ticket in admin</a></p>',1,1,0,'support',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(35,'ticket_replied','Support — New Reply (to customer)','[{ticket_number}] New reply on: {ticket_subject}','<h1>You have a new reply</h1><p>Hi {user_name},</p><p>Our support team has replied to your ticket <strong>{ticket_number}</strong> — \"{ticket_subject}\".</p><p><a href=\"{ticket_url}\">Read the reply</a></p><p>— The {site_name} support team</p>',1,1,0,'support',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(36,'ticket_replied_admin','Support — Customer Replied (to support team)','[{ticket_number}] {customer_name} replied: {ticket_subject}','<h1>Customer replied</h1><p>Hi {user_name},</p><p><strong>{customer_name}</strong> posted a new reply on ticket <strong>{ticket_number}</strong> — \"{ticket_subject}\".</p><p><a href=\"{ticket_url}\">Open ticket in admin</a></p>',1,1,0,'support',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(37,'ticket_resolved','Support — Ticket Resolved (to customer)','[{ticket_number}] Your ticket has been resolved','<h1>Ticket resolved</h1><p>Hi {user_name},</p><p>Your ticket <strong>{ticket_number}</strong> — \"{ticket_subject}\" — has been marked as resolved.</p><p>If the issue is not fully sorted, just reply on the ticket and it will reopen.</p><p><a href=\"{ticket_url}\">View your ticket</a></p><p>— The {site_name} support team</p>',1,1,0,'support',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(38,'export_ready','Export — Your Data Is Ready to Download','Your data export is ready to download','<h1>Your data export is ready</h1><p>Hi {user_name},</p><p>The copy of your data you requested has finished processing and is ready to download.</p><p><a href=\"{download_url}\">Download your data</a></p><p>You need to be signed in to download it, and the file is deleted automatically on <strong>{expires_at}</strong>. After that you can request a fresh export at any time.</p><p>— {site_name}</p>',1,1,0,'export',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(39,'comment_approved','Content — Blog Comment Approved','Your comment on \"{post_title}\" is now live','<h1>Your comment is live</h1><p>Hi {user_name},</p><p>Your comment on <strong>{post_title}</strong> has been approved and is now visible to everyone.</p><p><a href=\"{comment_url}\">View your comment</a></p><p>— {site_name}</p>',1,1,0,'content',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(40,'tool_review_approved','Content — Tool Review Approved','Your review of {tool_name} is now live','<h1>Your review is live</h1><p>Hi {user_name},</p><p>Thanks for reviewing <strong>{tool_name}</strong>. Your review has been approved and is now visible to everyone.</p><p><a href=\"{review_url}\">View your review</a></p><p>— {site_name}</p>',1,1,0,'content',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(41,'maintenance_scheduled','Maintenance — Going Offline','{site_name} is going down for maintenance','<h1>{maintenance_title}</h1><p>Hi {user_name},</p><p>{maintenance_message}</p><p>Expected back online: <strong>{restoration_time}</strong></p><p>Sorry for the interruption — we will email you as soon as we are live again.</p><p>— {site_name}</p>',1,1,0,'maintenance',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(42,'maintenance_completed','Maintenance — Back Online','{site_name} is back online','<h1>We are back</h1><p>Hi {user_name},</p><p>Maintenance is complete and {site_name} is available again. Thanks for your patience.</p><p><a href=\"{site_url}\">Go to your dashboard</a></p><p>— {site_name}</p>',1,1,0,'maintenance',NULL,'2026-08-05 15:00:52','2026-08-05 15:00:52');
