INSERT INTO `sms_campaigns` (`id`, `message`, `action_url`, `action_label`, `recipient_count`, `sent_count`, `failed_count`, `status`, `created_by_admin_id`, `started_at`, `finished_at`, `created_at`, `updated_at`) VALUES (1,'MakeAI: your monthly credits have just reset. Log in to start creating.','http://localhost/user/dashboard','Open dashboard',27,25,2,'sent',2,'2026-07-15 09:56:00','2026-07-15 10:16:00','2026-07-15 09:56:00','2026-08-05 15:01:38'),(2,'Flash sale: 30% off annual plans for the next 48 hours only.','http://localhost/pricing','View plans',23,20,3,'sent',2,'2026-07-27 09:37:00','2026-07-27 09:43:00','2026-07-27 09:37:00','2026-08-05 15:01:38'),(3,'New in MakeAI: document collections let you group and share your work.',NULL,NULL,16,10,1,'sending',2,'2026-08-05 10:29:00',NULL,'2026-08-05 10:29:00','2026-08-05 15:01:38'),(4,'Reminder: your subscription renews next week. Update billing details if needed.','http://localhost/user/dashboard/billing','Billing settings',0,0,0,'draft',2,NULL,NULL,'2026-08-04 13:43:00','2026-08-04 13:43:00');
