INSERT INTO `support_departments` (`id`, `name`, `slug`, `description`, `email`, `assigned_role_id`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (1,'General','general','General product and account questions.',NULL,3,1,10,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(2,'Technical','technical','Bug reports, errors, and technical help.',NULL,3,1,20,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(3,'Billing','billing','Payments, invoices, and subscription questions.',NULL,3,1,30,'2026-08-05 15:00:52','2026-08-05 15:00:52'),(4,'Feature Request','feature-request','Ideas and product improvement requests.',NULL,3,1,40,'2026-08-05 15:00:52','2026-08-05 15:00:52');
