INSERT INTO `support_tickets` (`id`, `ticket_number`, `user_id`, `department_id`, `assigned_to`, `subject`, `status`, `priority`, `source`, `first_response_at`, `resolved_at`, `closed_at`, `last_reply_at`, `last_reply_by`, `satisfaction_rating`, `satisfaction_comment`, `user_last_read_at`, `admin_last_read_at`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'DEMO-TKT-1001',2,3,2,'Invoice for the annual plan shows our old company name','closed','medium','email','2026-07-10 18:01:14','2026-07-11 13:01:14','2026-07-13 15:01:14','2026-07-11 17:01:14','user',5,'Reissued the same day and explained exactly what changed. Excellent.','2026-07-11 17:21:14','2026-07-11 17:06:14','2026-07-10 15:01:14','2026-07-11 17:01:14',NULL),(2,'DEMO-TKT-1002',2,2,2,'Bulk export of my documents times out at around 400 files','resolved','high','web','2026-07-27 19:01:14','2026-07-28 22:01:14',NULL,'2026-07-28 21:01:14','admin',NULL,NULL,'2026-07-28 21:21:14','2026-07-28 21:06:14','2026-07-27 15:01:14','2026-07-28 21:01:14',NULL),(3,'DEMO-TKT-1003',2,2,2,'Brand voice settings are ignored in long-form blog output','in_progress','high','web','2026-07-31 17:01:14',NULL,NULL,'2026-08-01 17:01:14','admin',NULL,NULL,'2026-08-01 17:21:14','2026-08-01 17:06:14','2026-07-31 15:01:14','2026-08-01 17:01:14',NULL),(4,'DEMO-TKT-1004',2,1,2,'Change the PayPal address my affiliate payouts are sent to','waiting_user','medium','web','2026-08-03 20:01:14',NULL,NULL,'2026-08-03 20:01:14','admin',NULL,NULL,'2026-08-03 15:11:14','2026-08-03 20:06:14','2026-08-03 15:01:14','2026-08-03 20:01:14',NULL),(5,'DEMO-TKT-1005',2,4,NULL,'Add a scheduled queue for generated social captions','open','low','web',NULL,NULL,NULL,'2026-08-04 19:01:14','user',NULL,NULL,'2026-08-04 19:21:14','2026-08-04 19:06:14','2026-08-04 19:01:14','2026-08-04 19:01:14',NULL),(6,'DEMO-TKT-1006',2,3,NULL,'Charged twice for the annual renewal','open','urgent','web',NULL,NULL,NULL,'2026-08-05 09:01:14','user',NULL,NULL,'2026-08-05 09:21:14','2026-08-05 09:06:14','2026-08-05 09:01:14','2026-08-05 09:01:14',NULL),(7,'DEMO-TKT-0001',3,3,NULL,'Billing question about invoice timing','open','low','email',NULL,NULL,NULL,'2026-07-22 15:01:22','user',NULL,NULL,'2026-07-22 16:01:22',NULL,'2026-07-22 15:01:22','2026-07-22 15:01:22',NULL),(8,'DEMO-TKT-0002',4,2,2,'Login issue on mobile device','in_progress','medium','web','2026-07-23 16:01:22',NULL,NULL,'2026-07-23 21:01:22','user',NULL,NULL,'2026-07-23 22:01:22','2026-07-23 16:01:22','2026-07-23 15:01:22','2026-07-23 21:01:22',NULL),(9,'DEMO-TKT-0003',5,1,2,'Need help with plan upgrade','resolved','high','api','2026-07-24 17:01:22','2026-07-25 15:01:22',NULL,'2026-07-25 09:01:22','admin',NULL,NULL,'2026-07-25 10:01:22','2026-07-25 09:01:22','2026-07-24 15:01:22','2026-07-25 09:01:22',NULL),(10,'DEMO-TKT-0004',6,2,2,'AI response is slower than expected','closed','low','email','2026-07-25 18:01:22','2026-07-26 15:01:22','2026-07-27 15:01:22','2026-07-26 11:01:22','admin',4,'Issue was resolved quickly.','2026-07-26 12:01:22','2026-07-26 11:01:22','2026-07-25 15:01:22','2026-07-26 11:01:22',NULL),(11,'DEMO-TKT-0005',7,3,NULL,'Billing question about invoice timing','open','medium','web',NULL,NULL,NULL,'2026-07-26 15:01:22','user',NULL,NULL,'2026-07-26 16:01:22',NULL,'2026-07-26 15:01:22','2026-07-26 15:01:22',NULL),(12,'DEMO-TKT-0006',8,2,2,'Login issue on mobile device','in_progress','high','api','2026-07-27 16:01:22',NULL,NULL,'2026-07-27 21:01:22','user',NULL,NULL,'2026-07-27 22:01:22','2026-07-27 16:01:22','2026-07-27 15:01:22','2026-07-27 21:01:22',NULL),(13,'DEMO-TKT-0007',9,1,2,'Need help with plan upgrade','resolved','low','email','2026-07-28 17:01:22','2026-07-29 15:01:22',NULL,'2026-07-29 09:01:22','admin',NULL,NULL,'2026-07-29 10:01:22','2026-07-29 09:01:22','2026-07-28 15:01:22','2026-07-29 09:01:22',NULL),(14,'DEMO-TKT-0008',10,2,2,'AI response is slower than expected','closed','medium','web','2026-07-29 18:01:22','2026-07-30 15:01:22','2026-07-31 15:01:22','2026-07-30 11:01:22','admin',5,'Issue was resolved quickly.','2026-07-30 12:01:22','2026-07-30 11:01:22','2026-07-29 15:01:22','2026-07-30 11:01:22',NULL),(15,'DEMO-TKT-0009',11,3,NULL,'Billing question about invoice timing','open','high','api',NULL,NULL,NULL,'2026-07-30 15:01:22','user',NULL,NULL,'2026-07-30 16:01:22',NULL,'2026-07-30 15:01:22','2026-07-30 15:01:22',NULL),(16,'DEMO-TKT-0010',12,2,2,'Login issue on mobile device','in_progress','low','email','2026-07-31 16:01:22',NULL,NULL,'2026-07-31 21:01:22','user',NULL,NULL,'2026-07-31 22:01:22','2026-07-31 16:01:22','2026-07-31 15:01:22','2026-07-31 21:01:22',NULL),(17,'DEMO-TKT-0011',3,1,2,'Need help with plan upgrade','resolved','medium','web','2026-08-01 17:01:22','2026-08-02 15:01:22',NULL,'2026-08-02 09:01:22','admin',NULL,NULL,'2026-08-02 10:01:22','2026-08-02 09:01:22','2026-08-01 15:01:22','2026-08-02 09:01:22',NULL),(18,'DEMO-TKT-0012',4,2,2,'AI response is slower than expected','closed','high','api','2026-08-02 18:01:22','2026-08-03 15:01:22','2026-08-04 15:01:22','2026-08-03 11:01:22','admin',4,'Issue was resolved quickly.','2026-08-03 12:01:22','2026-08-03 11:01:22','2026-08-02 15:01:22','2026-08-03 11:01:22',NULL);
