INSERT INTO `tool_chain_runs` (`id`, `ulid`, `chain_id`, `user_id`, `status`, `input`, `step_outputs`, `total_tokens`, `error`, `total_credits`, `started_at`, `completed_at`, `created_at`, `updated_at`) VALUES (1,'01KZ972QSFTWBMCQPC4K3NXMFV',1,2,'completed','How AI writing assistants change agency retainers','[{\"step\": 1, \"output\": \"How AI Writing Assistants Are Changing Agency Retainers\\n\\nRetainers used to be priced on hours. When a first draft takes twenty minutes instead of a morning, that maths stops working — and the agencies winning right now have already repriced around outcomes rather than time...\", \"tokens\": 1480, \"credits\": 26, \"tool_slug\": \"abandoned-cart-email\"}, {\"step\": 2, \"output\": \"Agency retainers are being repriced around outcomes, not hours. See how AI drafting changes scoping, margins and what clients actually pay for.\", \"tokens\": 660, \"credits\": 12, \"tool_slug\": \"about-us-page\"}]',2140,NULL,38.0000,'2026-08-05 10:01:13','2026-08-05 10:01:40','2026-08-05 10:01:13','2026-08-05 10:01:40'),(2,'01KZ972QSK0X0QV4RWS56GG4GY',2,2,'completed','Scheduled publishing for generated social captions','[{\"step\": 1, \"output\": \"Queue every caption you generate and let them publish themselves. Scheduled publishing turns a folder of drafts into a filled week — pick the slot, approve the copy, and move on to the next client.\", \"tokens\": 1620, \"credits\": 29, \"tool_slug\": \"academic-cover-letter\"}, {\"step\": 2, \"output\": \"Stop pasting captions into three tools.\\nGenerate, queue, publish — one workflow, one tab.\\nBuilt for the people who run five brands before lunch.\", \"tokens\": 1180, \"credits\": 21, \"tool_slug\": \"action-plan\"}, {\"step\": 3, \"output\": \"New: schedule the captions you just generated, without leaving the editor.\\n\\nPick a slot, approve the copy, done. Your week fills itself.\\n\\n#marketing #ai #socialmedia\", \"tokens\": 1180, \"credits\": 21, \"tool_slug\": \"ad-hook-generator\"}]',3980,NULL,71.0000,'2026-08-04 09:01:13','2026-08-04 09:02:34','2026-08-04 09:01:13','2026-08-04 09:02:34'),(3,'01KZ972QSPXK07T3F1WG2X4DVY',1,2,'failed','Q4 reporting checklist for marketing teams','[{\"step\": 1, \"output\": \"The Q4 Reporting Checklist for Marketing Teams\\n\\nClose the quarter without the usual scramble: agree the numbers that matter in week one, automate the pulls, and keep a running narrative so the deck writes itself...\", \"tokens\": 1490, \"credits\": 26, \"tool_slug\": \"abandoned-cart-email\"}]',1490,'Step 2 failed: the provider returned a rate-limit error. Credits for the completed step were not refunded.',26.0000,'2026-08-03 11:01:13','2026-08-03 11:02:12','2026-08-03 11:01:13','2026-08-03 11:02:12'),(4,'01KZ972QSSH204H77SS12E886Z',3,2,'completed','Issue 42 — what shipped this month','[{\"step\": 1, \"output\": \"1. Everything we shipped this month (in 4 minutes)\\n2. Issue 42: the features you asked for\\n3. Your month in one email\", \"tokens\": 420, \"credits\": 7, \"tool_slug\": \"abstract-writer\"}, {\"step\": 2, \"output\": \"This month went to the unglamorous work: exports that finish, a queue that keeps your brand voice from step one to step nine, and a chain builder that no longer forgets its field mapping...\", \"tokens\": 1440, \"credits\": 26, \"tool_slug\": \"abandoned-cart-email\"}]',1860,NULL,33.0000,'2026-07-30 15:01:13','2026-07-30 15:02:43','2026-07-30 15:01:13','2026-07-30 15:02:43');
